/* -*- Source -*-
 * Minimal MiniZinc frontend for the walking skeleton.
 *
 * Supports declarations, constraints and a solve item over a small expression
 * grammar. Everything else is refused with E_UNSUPPORTED_CONSTRUCT rather than
 * approximated, so the coverage table stays honest.
 *
 * Copyright (C) 2026 Fuqi Jia
 */

#include "somtparser/languages/minizinc.h"
#include "mzn_json_value.h"
#include "mzn_expression_analysis.h"

#include <algorithm>
#include <cctype>
#include <charconv>
#include <cstddef>
#include <filesystem>
#include <functional>
#include <iterator>
#include <limits>
#include <optional>
#include <fstream>
#include <memory>
#include <new>
#include <sstream>
#include <string>
#include <string_view>
#include <system_error>
