    std::unordered_map<std::string, Span> integer_domains_;
    std::unordered_map<std::string, Span> array_element_domains_;
    std::unordered_map<std::string, H::ExprPtr> constant_parameter_arrays_;
    std::unordered_map<std::string, std::pair<H::ExprPtr, H::ExprPtr>> functional_parameter_tables_;
    std::unordered_map<std::string, H::ExprPtr> compact_parameter_tables_;
    std::vector<H::FunDecl> parameter_table_definitions_;
    std::vector<H::DatatypeDecl> optional_datatypes_;
    std::unordered_map<std::string, H::Sort> optional_value_sorts_;
    std::size_t decision_read_epoch_ = 0;
    /** A parameter array: its values and the index its first element carries.
     *  Values rather than a sort, because it is data -- see parseParamArrayDecl. */
    struct ParamArray {
        std::string enum_type;
        SharedParameterStorage<std::vector<std::string>> cell_enum_types;
        bool json_strings = false;
        // JSON array positions carry extents but no index-origin semantics;
        // the declared axes therefore apply to JSON arrays positionally.
        bool json_shape_implicit = false;
        long long              lo = 0;
        bool                   is_bool = false;
        bool                   is_real = false;
        bool                   is_string = false;
        /** Row-major, the last dimension varying fastest -- the same
         *  convention flatIndex uses for decision arrays. Holding one
         *  convention in two places would be a way for them to disagree, and
         *  a disagreement here reads a different cell rather than failing. */
        SharedParameterStorage<std::vector<long long>> values;
        /** Exact rational Real cells, keyed by the parallel cell offset.
         *  Integer JSON cells remain in `values` until a Float declaration
         *  supplies the widening context. */
        SharedParameterStorage<std::unordered_map<std::size_t, std::string>> real_cells;
        SharedParameterStorage<std::vector<std::string>> string_values;
        std::vector<bool> string_is_enum;
        bool is_optional = false;
        // Absence is separate from the payload: every integer, including zero,
        // remains a possible present value. This is not a decision-array hole.
        std::vector<bool> absent;
        bool isAbsent(std::size_t at) const {
            return at < absent.size() && absent[at];
        }
        bool is_set = false;
        bool list_set_coercion = false;
        SharedParameterStorage<std::vector<FixedIntSet>> set_values;
        SharedParameterStorage<std::vector<DataSetValue>> data_set_values;
        /** Which cells were written `_`, parallel to `values`. Empty means
         *  none, which is every parameter array and most decision ones.
         *
         *  A hole is not a value, so it cannot live in `values`: every
         *  `long long` is a legal cell. It means the cell was left to the
         *  solver, so reading it must yield the DECLARED array's own element
         *  rather than a constant -- see arrayElementValue, where a fixed
         *  cell inlines its number and a hole becomes a select. */
        std::vector<bool>      hole;
        bool isHole(std::size_t at) const {
            return at < hole.size() && hole[at];
        }
        /** The declared shape, once a declaration has given one. Ordinary
         *  literals carry their implicit 1-based axes; JSON is separately
         *  marked as positional. */
        std::vector<Span>      dims;
        /** Exact explicit index sets carried by arrayNd(...), independent of
         *  the declaration's index origins until they have been compared. */
        std::vector<Span>      literal_dims;
        /** Exact source constructor dimensions, including names which were
         *  not bound until model declarations were read. */
        std::vector<ArrayConstructorIndex> constructor_index_sets;
        /** JSON nested arrays carry shape, but no source index origins. */
        bool                   constructor_indices_implicit = false;
        /** Rank is explicit even for a zero-cell matrix. Extents alone cannot
         *  distinguish a rank-two empty literal from an empty rank-one list. */
        bool                   literal_is_matrix = false;
        /** The shape the LITERAL was written in, or 0/0 for a flat one. Kept
         *  separately from `dims` so a declaration can check that the value it
         *  was handed has the shape it declares -- a 3x2 literal supplied for
         *  an `array[1..2,1..3]` has the right number of cells and the wrong
         *  arrangement, and only this distinguishes them. */
        long long              literal_rows = 0;
        long long              literal_cols = 0;

        /** Row-major offset of @p index, or -1 when it is out of range. */
        long long offsetOf(const std::vector<long long>& index) const {
            if (dims.empty()) {
                if (index.size() != 1) { return -1; }
                if (index[0] < lo) { return -1; }
                // The mathematical difference may exceed LLONG_MAX even
                // though both input coordinates fit. Compare before narrowing.
                const auto off = static_cast<unsigned long long>(index[0])
                               - static_cast<unsigned long long>(lo);
                return off >= values.size() ? -1 : static_cast<long long>(off);
            }
            if (index.size() != dims.size()) { return -1; }
            long long off = 0;
            for (std::size_t k = 0; k < dims.size(); ++k) {
                if (index[k] < dims[k].lo || index[k] > dims[k].hi) { return -1; }
                off = off * dims[k].size() + (index[k] - dims[k].lo);
            }
            return (off >= 0 && off < static_cast<long long>(values.size()))
                       ? off : -1;
        }

        std::string shapeText() const {
            if (dims.empty()) {
                return std::to_string(lo) + ".."
                     + std::to_string(lo + static_cast<long long>(values.size()) - 1);
            }
            std::string s;
            for (std::size_t k = 0; k < dims.size(); ++k) {
                if (k != 0) { s += ","; }
                s += std::to_string(dims[k].lo) + ".." + std::to_string(dims[k].hi);
            }
            return s;
        }
    };
